/* Replay is an ordinary original campaign start from each genuine terminal. */
#define main prior_reentry_main
#include "test_em_web_campaign_reentry.c"
#undef main
static void replay(const char*path){load(path);int h=em_web_campaign_house(&c),m=em_web_campaign_mission(&c);uint64_t end=c.vdp.frames+30;while(!em_web_campaign_terminal(&c)&&c.vdp.frames<end)step();check(em_web_campaign_terminal(&c),"original terminal observed");if(em_web_campaign.scene&&!strcmp(em_web_campaign.scene,"credits"))m=9;check(em_web_campaign_request(&c,h,m),"queue same original house/mission replay");end=c.vdp.frames+6000;while(em_web_campaign.stage!=4&&c.vdp.frames<end)step();check(em_web_campaign.stage==4,"terminal replay follows original NewHouse/password flow");frames(400);check(em_web_campaign.pending&&!em_web_campaign.starts,"replayed briefing remains manual");end=c.vdp.frames+6000;uint64_t next=c.vdp.frames;while(em_web_campaign.pending&&c.vdp.frames<end){if(c.vdp.frames>=next&&em_web_campaign.poll_frame+3>=c.vdp.frames&&!em_web_campaign.input_pending){em_web_campaign_input_request(&c,em_web_campaign.poll_pc==0x25cb2?5:0,em_web_campaign.poll_pc==0x25cb2?0:PAD_A);next=c.vdp.frames+45;}step();}check(!c.fault&&!em_web_campaign.pending&&em_web_campaign_house(&c)==h&&em_web_campaign_mission(&c)==m&&dune_mouse_context(&c)==1,"same native scenario replay loaded");check(!em_web_campaign.outcome_seq,"replay grants no completion");printf("PASS terminal replay %s -> original house%d mission%d, manual briefing, zero false wins\n",path,h,m);fflush(stdout);}
int main(void){replay(".local/campaign-scenes/house1-mission01-defeat-results.cpu.bin");replay(".local/campaign-scenes/house1-credits.cpu.bin");return 0;}
